import{_ as r,o as t,c as l,a3 as i}from"./chunks/framework.BrO6lPIi.js";const m=JSON.parse('{"title":"MCP 工具注册表","description":"本文聚焦 Agent 端的 MCP 工具注册表，解释其如何从配置中加载 MCP Server、建立连接、发现并缓存工具、暴露 HTTP API，以及扩展端如何消费这些工具。","frontmatter":{"title":"MCP 工具注册表","description":"本文聚焦 Agent 端的 MCP 工具注册表，解释其如何从配置中加载 MCP Server、建立连接、发现并缓存工具、暴露 HTTP API，以及扩展端如何消费这些工具。"},"headers":[],"relativePath":"工具生态系统/MCP-协议扩展/MCP-工具注册表/index.md","filePath":"工具生态系统/MCP-协议扩展/MCP-工具注册表/index.md","lastUpdated":null}'),a={name:"工具生态系统/MCP-协议扩展/MCP-工具注册表/index.md"};function n(s,e,o,c,g,p){return t(),l("div",null,[...e[0]||(e[0]=[i(`<h1 id="mcp-工具注册表" tabindex="-1">MCP 工具注册表 <a class="header-anchor" href="#mcp-工具注册表" aria-label="Permalink to &quot;MCP 工具注册表&quot;">​</a></h1><details class="details custom-block"><summary>本文引用的源码文件</summary><p><strong>本文引用的文件</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/mcp/registry.js" target="_blank" rel="noreferrer">agent/src/mcp/registry.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/mcp/client.js" target="_blank" rel="noreferrer">agent/src/mcp/client.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/mcp/mcp-config.js" target="_blank" rel="noreferrer">agent/src/mcp/mcp-config.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js" target="_blank" rel="noreferrer">agent/src/server.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/tool-executor.js" target="_blank" rel="noreferrer">src/background/tool-executor.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/tool-panel.js" target="_blank" rel="noreferrer">src/side_panel/tool-panel.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/agent-manager.js" target="_blank" rel="noreferrer">src/side_panel/agent-manager.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/shared/locales/en.js" target="_blank" rel="noreferrer">src/shared/locales/en.js</a></li></ul></details><h2 id="目录" tabindex="-1">目录 <a class="header-anchor" href="#目录" aria-label="Permalink to &quot;目录&quot;">​</a></h2><ol><li><a href="#引言">引言</a></li><li><a href="#项目结构">项目结构</a></li><li><a href="#核心组件">核心组件</a></li><li><a href="#架构总览">架构总览</a></li><li><a href="#详细组件分析">详细组件分析</a></li><li><a href="#依赖关系分析">依赖关系分析</a></li><li><a href="#性能与并发控制">性能与并发控制</a></li><li><a href="#安全与错误处理">安全与错误处理</a></li><li><a href="#生命周期管理">生命周期管理</a></li><li><a href="#分组命名空间与版本机制">分组、命名空间与版本机制</a></li><li><a href="#最佳实践">最佳实践</a></li><li><a href="#自定义工具开发指南">自定义工具开发指南</a></li><li><a href="#故障排查">故障排查</a></li><li><a href="#结论">结论</a></li></ol><h2 id="引言" tabindex="-1">引言 <a class="header-anchor" href="#引言" aria-label="Permalink to &quot;引言&quot;">​</a></h2><p>本文聚焦 Agent 端的 MCP 工具注册表，解释其如何从配置中加载 MCP Server、建立连接、发现并缓存工具、暴露 HTTP API，以及扩展端如何消费这些工具。需要特别强调：Agent 是独立 Node.js 进程；修改 Agent 源码后必须重启进程，新接口和逻辑才会生效。</p><h2 id="项目结构" tabindex="-1">项目结构 <a class="header-anchor" href="#项目结构" aria-label="Permalink to &quot;项目结构&quot;">​</a></h2><p>MCP 相关代码主要分布在 Agent 端 <code>agent/src/mcp</code> 三个文件，并由 <code>agent/src/server.js</code> 暴露 HTTP 接口；扩展端通过 background 脚本拉取工具列表并动态注入到工具执行器。</p><pre class="mermaid">graph TB
subgraph &quot;Agent 端&quot;
REG[&quot;mcp/registry.js&lt;br/&gt;注册表&quot;]
CLI[&quot;mcp/client.js&lt;br/&gt;MCP 客户端&quot;]
CFG[&quot;mcp/mcp-config.js&lt;br/&gt;配置缓存与写锁&quot;]
SRV[&quot;server.js&lt;br/&gt;HTTP 路由&quot;]
end
subgraph &quot;扩展端&quot;
BE[&quot;background/tool-executor.js&lt;br/&gt;拉取并注入 MCP 工具&quot;]
UI[&quot;side_panel/tool-panel.js&lt;br/&gt;服务级开关 UI&quot;]
AM[&quot;side_panel/agent-manager.js&lt;br/&gt;按服务聚合工具&quot;]
end
SRV --&gt; REG
REG --&gt; CLI
REG --&gt; CFG
BE --&gt; SRV
UI --&gt; BE
AM --&gt; BE
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L1900-L2021" target="_blank" rel="noreferrer">agent/src/server.js#L1900-L2021</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/mcp/registry.js#L1-L181" target="_blank" rel="noreferrer">agent/src/mcp/registry.js#L1-L181</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/mcp/client.js#L1-L184" target="_blank" rel="noreferrer">agent/src/mcp/client.js#L1-L184</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/mcp/mcp-config.js#L1-L129" target="_blank" rel="noreferrer">agent/src/mcp/mcp-config.js#L1-L129</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/tool-executor.js#L547-L588" target="_blank" rel="noreferrer">src/background/tool-executor.js#L547-L588</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/tool-panel.js#L215-L244" target="_blank" rel="noreferrer">src/side_panel/tool-panel.js#L215-L244</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/agent-manager.js#L902-L928" target="_blank" rel="noreferrer">src/side_panel/agent-manager.js#L902-L928</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/mcp/registry.js#L1-L181" target="_blank" rel="noreferrer">agent/src/mcp/registry.js#L1-L181</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/mcp/client.js#L1-L184" target="_blank" rel="noreferrer">agent/src/mcp/client.js#L1-L184</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/mcp/mcp-config.js#L1-L129" target="_blank" rel="noreferrer">agent/src/mcp/mcp-config.js#L1-L129</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L1900-L2021" target="_blank" rel="noreferrer">agent/src/server.js#L1900-L2021</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/tool-executor.js#L547-L588" target="_blank" rel="noreferrer">src/background/tool-executor.js#L547-L588</a></li></ul><h2 id="核心组件" tabindex="-1">核心组件 <a class="header-anchor" href="#核心组件" aria-label="Permalink to &quot;核心组件&quot;">​</a></h2><ul><li><strong>注册表（registry.js）</strong>：维护已连接的 MCP Client 实例，提供初始化、查询工具、调用工具、连接/断开服务器、关闭所有连接等能力。</li><li><strong>MCP 客户端（client.js）</strong>：封装 Model Context Protocol SDK，负责创建传输层（stdio/SSE/streamableHttp/websocket）、连接远端 MCP Server、列出工具、调用工具、断开连接。</li><li><strong>配置管理（mcp-config.js）</strong>：读写 <code>~/.ai-helper-agent/mcp_servers.json</code>，带内存缓存、mtime 失效、写入互斥锁。</li><li><strong>HTTP 路由（server.js）</strong>：将 MCP 管理操作映射为 <code>/api/mcp/*</code> 接口，并在请求入口同步语言设置。</li><li><strong>扩展端工具注入（tool-executor.js）</strong>：根据全局开关、禁用服务器列表、强制下发列表，把 MCP 工具动态注入到扩展的工具执行体系。</li><li><strong>UI 分组与过滤（tool-panel.js、agent-manager.js）</strong>：MCP 工具按服务维度展示，支持“服务级开放/关闭”。</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/mcp/registry.js#L1-L181" target="_blank" rel="noreferrer">agent/src/mcp/registry.js#L1-L181</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/mcp/client.js#L1-L184" target="_blank" rel="noreferrer">agent/src/mcp/client.js#L1-L184</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/mcp/mcp-config.js#L1-L129" target="_blank" rel="noreferrer">agent/src/mcp/mcp-config.js#L1-L129</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L1900-L2021" target="_blank" rel="noreferrer">agent/src/server.js#L1900-L2021</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/tool-executor.js#L547-L588" target="_blank" rel="noreferrer">src/background/tool-executor.js#L547-L588</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/tool-panel.js#L215-L244" target="_blank" rel="noreferrer">src/side_panel/tool-panel.js#L215-L244</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/agent-manager.js#L902-L928" target="_blank" rel="noreferrer">src/side_panel/agent-manager.js#L902-L928</a></li></ul><h2 id="架构总览" tabindex="-1">架构总览 <a class="header-anchor" href="#架构总览" aria-label="Permalink to &quot;架构总览&quot;">​</a></h2><p>MCP 工具注册表不是传统意义上的“文件系统扫描 + 模块加载”系统，而是“配置驱动 + 协议客户端 + 运行时连接池”的系统。工具发现来自远端 MCP Server 的 <code>listTools</code>，而不是本地目录扫描。</p><pre class="mermaid">sequenceDiagram
participant Ext as &quot;扩展端 Background&quot;
participant Srv as &quot;Agent server.js&quot;
participant Reg as &quot;registry.js&quot;
participant Cli as &quot;client.js&quot;
participant Mps as &quot;远端 MCP Server&quot;
Ext-&gt;&gt;Srv : GET /api/mcp/tools
Srv-&gt;&gt;Reg : getMcpTools()
Reg--&gt;&gt;Srv : { success, tools[] }
Srv--&gt;&gt;Ext : JSON 工具列表
Ext-&gt;&gt;Srv : POST /api/mcp/call { serverId, toolName, args }
Srv-&gt;&gt;Reg : callMcpTool(serverId, toolName, args)
Reg-&gt;&gt;Cli : client.callTool(toolName, args)
Cli-&gt;&gt;Mps : MCP callTool
Mps--&gt;&gt;Cli : result
Cli--&gt;&gt;Reg : { success, content, raw }
Reg--&gt;&gt;Srv : 结果
Srv--&gt;&gt;Ext : JSON 响应
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L1916-L1922" target="_blank" rel="noreferrer">agent/src/server.js#L1916-L1922</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L2018-L2021" target="_blank" rel="noreferrer">agent/src/server.js#L2018-L2021</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/mcp/registry.js#L89-L128" target="_blank" rel="noreferrer">agent/src/mcp/registry.js#L89-L128</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/mcp/client.js#L96-L157" target="_blank" rel="noreferrer">agent/src/mcp/client.js#L96-L157</a></li></ul><h2 id="详细组件分析" tabindex="-1">详细组件分析 <a class="header-anchor" href="#详细组件分析" aria-label="Permalink to &quot;详细组件分析&quot;">​</a></h2><h3 id="注册表-registry-js" tabindex="-1">注册表：registry.js <a class="header-anchor" href="#注册表-registry-js" aria-label="Permalink to &quot;注册表：registry.js&quot;">​</a></h3><p>注册表是 MCP 能力的统一入口，职责包括：</p><ul><li>启动时遍历配置中的启用服务器，逐个连接并缓存 Client。</li><li>提供扁平化工具列表，包含 <code>serverId</code>、<code>serverName</code>、<code>name</code>、<code>description</code>、<code>inputSchema</code>。</li><li>转发工具调用到对应 Client。</li><li>提供连接/断开/关闭全部连接的生命周期方法。</li><li>重新导出配置管理函数，供 server.js 直接调用。</li></ul><p>关键行为要点：</p><ul><li>未启用的服务器在初始化阶段被跳过。</li><li>连接失败会记录失败服务器列表并输出警告日志。</li><li>工具调用前校验 Client 是否存在且已连接。</li><li>关闭时对所有 Client 调用 disconnect，并清空 Map。</li></ul><pre class="mermaid">classDiagram
class Registry {
+initializeMcpRegistry() Promise
+getMcpServersStatus() Object
+getMcpTools(serverId?) Object
+callMcpTool(serverId, toolName, args) Promise
+connectMcpServer(serverId) Promise
+disconnectMcpServer(serverId) Promise
+shutdownMcpRegistry() Promise
}
class McpClient {
+connect() Promise
+callTool(toolName, args) Promise
+disconnect() Promise
+getStatus() Object
}
class Config {
+loadMcpConfig() Object
+addMcpServer(server) Promise
+removeMcpServer(serverId) Promise
+toggleMcpServer(serverId, enabled) Promise
}
Registry --&gt; McpClient : &quot;管理多个实例&quot;
Registry --&gt; Config : &quot;读取/更新配置&quot;
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/mcp/registry.js#L1-L181" target="_blank" rel="noreferrer">agent/src/mcp/registry.js#L1-L181</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/mcp/client.js#L35-L184" target="_blank" rel="noreferrer">agent/src/mcp/client.js#L35-L184</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/mcp/mcp-config.js#L37-L129" target="_blank" rel="noreferrer">agent/src/mcp/mcp-config.js#L37-L129</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/mcp/registry.js#L1-L181" target="_blank" rel="noreferrer">agent/src/mcp/registry.js#L1-L181</a></li></ul><h3 id="mcp-客户端-client-js" tabindex="-1">MCP 客户端：client.js <a class="header-anchor" href="#mcp-客户端-client-js" aria-label="Permalink to &quot;MCP 客户端：client.js&quot;">​</a></h3><p>McpClient 封装了 MCP SDK 的使用方式，支持多种传输协议：</p><ul><li>stdio：通过命令、参数、环境变量和工作目录启动子进程。</li><li>SSE：需要 URL，可选 headers。</li><li>streamableHttp：需要 URL，可选 headers。</li><li>websocket：需要 URL。</li></ul><p>连接流程：</p><ol><li>根据配置创建传输层。</li><li>创建 SDK Client 并 connect。</li><li>获取 serverInfo 和 capabilities。</li><li>调用 listTools 缓存工具元数据。</li><li>标记 connected。</li></ol><p>工具调用流程：</p><ol><li>检查 connected。</li><li>调用 callTool。</li><li>解析 result.content 中的 text 内容。</li><li>返回 success/content/raw。</li></ol><pre class="mermaid">flowchart TD
Start([&quot;connect()&quot;]) --&gt; CreateTransport[&quot;根据 transport 类型创建传输层&quot;]
CreateTransport --&gt; Validate[&quot;校验必要字段&lt;br/&gt;url/command&quot;]
Validate --&gt; ConnectSDK[&quot;SDK Client.connect()&quot;]
ConnectSDK --&gt; FetchMeta[&quot;获取 serverInfo / capabilities&quot;]
FetchMeta --&gt; ListTools[&quot;listTools()&quot;]
ListTools --&gt; CacheTools[&quot;缓存 tools 数组&quot;]
CacheTools --&gt; MarkConnected[&quot;connected = true&quot;]
MarkConnected --&gt; Done([&quot;返回成功&quot;])
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/mcp/client.js#L50-L127" target="_blank" rel="noreferrer">agent/src/mcp/client.js#L50-L127</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/mcp/client.js#L1-L184" target="_blank" rel="noreferrer">agent/src/mcp/client.js#L1-L184</a></li></ul><h3 id="配置管理-mcp-config-js" tabindex="-1">配置管理：mcp-config.js <a class="header-anchor" href="#配置管理-mcp-config-js" aria-label="Permalink to &quot;配置管理：mcp-config.js&quot;">​</a></h3><p>配置路径位于用户主目录下的 <code>.ai-helper-agent/mcp_servers.json</code>。该模块提供：</p><ul><li>带 mtime 的内存缓存。</li><li>首次缺失时自动创建默认空配置。</li><li>解析失败时降级为空 servers 数组。</li><li>写入互斥锁，避免并发写破坏 JSON。</li><li>add/remove/toggle 等原子化配置变更。</li></ul><pre class="mermaid">flowchart TD
Load[&quot;loadMcpConfig()&quot;] --&gt; CheckMtime{&quot;缓存有效？&quot;}
CheckMtime --&gt; |是| ReturnCache[&quot;返回缓存&quot;]
CheckMtime --&gt; |否| Exists{&quot;文件存在？&quot;}
Exists --&gt; |否| CreateDefault[&quot;创建默认配置并缓存&quot;]
Exists --&gt; |是| ReadFile[&quot;读取并解析 JSON&quot;]
ReadFile --&gt; ParseOk{&quot;解析成功？&quot;}
ParseOk --&gt; |是| UpdateCache[&quot;更新缓存 mtime&quot;]
ParseOk --&gt; |否| Fallback[&quot;降级为空 servers 并记录错误&quot;]
UpdateCache --&gt; ReturnData[&quot;返回配置&quot;]
Fallback --&gt; ReturnData
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/mcp/mcp-config.js#L28-L64" target="_blank" rel="noreferrer">agent/src/mcp/mcp-config.js#L28-L64</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/mcp/mcp-config.js#L1-L129" target="_blank" rel="noreferrer">agent/src/mcp/mcp-config.js#L1-L129</a></li></ul><h3 id="http-路由-server-js" tabindex="-1">HTTP 路由：server.js <a class="header-anchor" href="#http-路由-server-js" aria-label="Permalink to &quot;HTTP 路由：server.js&quot;">​</a></h3><p>server.js 将 MCP 能力暴露为 REST 接口，主要包括：</p><ul><li><code>/api/mcp/servers</code>：GET 获取服务器状态。</li><li><code>/api/mcp/tools</code>：GET 获取工具列表，可传 <code>serverId</code> 过滤。</li><li><code>/api/mcp/call</code>：POST 调用工具。</li><li><code>/api/mcp/servers/connect</code>、<code>/api/mcp/servers/disconnect</code>、<code>/api/mcp/servers/toggle</code>、<code>/api/mcp/servers</code>（POST/DELETE）：管理服务器配置与连接。</li></ul><p>每个请求进入时，server.js 会将当前请求的语言同步到各子模块，包括 MCP 客户端和注册表。</p><pre class="mermaid">sequenceDiagram
participant C as &quot;客户端&quot;
participant R as &quot;server.js 路由&quot;
participant G as &quot;registry.js&quot;
participant L as &quot;client.js&quot;
C-&gt;&gt;R : POST /api/mcp/call
R-&gt;&gt;R : 校验 serverId/toolName
R-&gt;&gt;G : callMcpTool(serverId, toolName, args)
G-&gt;&gt;L : client.callTool(toolName, args)
L--&gt;&gt;G : { success, content, raw }
G--&gt;&gt;R : 结果
R--&gt;&gt;C : JSON 响应
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L1916-L1922" target="_blank" rel="noreferrer">agent/src/server.js#L1916-L1922</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/mcp/registry.js#L116-L128" target="_blank" rel="noreferrer">agent/src/mcp/registry.js#L116-L128</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/mcp/client.js#L129-L157" target="_blank" rel="noreferrer">agent/src/mcp/client.js#L129-L157</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L1900-L2021" target="_blank" rel="noreferrer">agent/src/server.js#L1900-L2021</a></li></ul><h3 id="扩展端工具注入-tool-executor-js" tabindex="-1">扩展端工具注入：tool-executor.js <a class="header-anchor" href="#扩展端工具注入-tool-executor-js" aria-label="Permalink to &quot;扩展端工具注入：tool-executor.js&quot;">​</a></h3><p>扩展端不会直接调用 MCP Server，而是先通过 Agent 的 <code>/api/mcp/tools</code> 拉取工具定义，再注入到扩展的工具执行器中。关键策略：</p><ul><li>有全局 MCP 开关，关闭则跳过加载。</li><li>每次加载前先清理之前注册的 MCP 工具。</li><li>并行拉取工具列表和服务器状态。</li><li>忽略 disabled 服务器的工具。</li><li>支持 forcedMcpServerIds 强制下发，绕过 deny-list。</li></ul><pre class="mermaid">flowchart TD
Entry([&quot;loadMcpTools()&quot;]) --&gt; GlobalCheck{&quot;全局 MCP 开启？&quot;}
GlobalCheck --&gt; |否| Skip[&quot;跳过加载&quot;]
GlobalCheck --&gt; |是| Clean[&quot;清理旧 MCP 工具&quot;]
Clean --&gt; FetchAll[&quot;并行获取 tools 和 servers&quot;]
FetchAll --&gt; HasTools{&quot;tools 非空？&quot;}
HasTools --&gt; |否| Skip
HasTools --&gt; |是| BuildDisabled[&quot;构建禁用服务器集合&quot;]
BuildDisabled --&gt; Inject[&quot;注入可用工具到执行器&quot;]
Inject --&gt; Done([&quot;完成&quot;])
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/tool-executor.js#L547-L588" target="_blank" rel="noreferrer">src/background/tool-executor.js#L547-L588</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/tool-executor.js#L547-L588" target="_blank" rel="noreferrer">src/background/tool-executor.js#L547-L588</a></li></ul><h3 id="ui-分组与服务级开关-tool-panel-js-与-agent-manager-js" tabindex="-1">UI 分组与服务级开关：tool-panel.js 与 agent-manager.js <a class="header-anchor" href="#ui-分组与服务级开关-tool-panel-js-与-agent-manager-js" aria-label="Permalink to &quot;UI 分组与服务级开关：tool-panel.js 与 agent-manager.js&quot;">​</a></h3><ul><li>tool-panel.js 明确说明：MCP 工具不参与工具级勾选，而是按“服务级开关”判定。</li><li>agent-manager.js 将工具按 serverId 聚合为服务对象，便于 UI 展示和计数。</li></ul><p>这意味着 MCP 的“分组”本质上是“服务分组”，而不是传统的 category 分类。</p><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/tool-panel.js#L215-L244" target="_blank" rel="noreferrer">src/side_panel/tool-panel.js#L215-L244</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/agent-manager.js#L902-L928" target="_blank" rel="noreferrer">src/side_panel/agent-manager.js#L902-L928</a></li></ul><h2 id="依赖关系分析" tabindex="-1">依赖关系分析 <a class="header-anchor" href="#依赖关系分析" aria-label="Permalink to &quot;依赖关系分析&quot;">​</a></h2><ul><li>registry.js 依赖 client.js 和 mcp-config.js。</li><li>server.js 依赖 registry.js 暴露的函数。</li><li>扩展端 tool-executor.js 依赖 Agent 的 HTTP API。</li><li>UI 层依赖 tool-executor.js 提供的工具列表和服务聚合结果。</li></ul><pre class="mermaid">graph LR
ToolExecutor[&quot;tool-executor.js&quot;] --&gt; ServerAPI[&quot;server.js /api/mcp/*&quot;]
ServerAPI --&gt; Registry[&quot;registry.js&quot;]
Registry --&gt; Client[&quot;client.js&quot;]
Registry --&gt; Config[&quot;mcp-config.js&quot;]
UIPanel[&quot;tool-panel.js / agent-manager.js&quot;] --&gt; ToolExecutor
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/tool-executor.js#L547-L588" target="_blank" rel="noreferrer">src/background/tool-executor.js#L547-L588</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L1900-L2021" target="_blank" rel="noreferrer">agent/src/server.js#L1900-L2021</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/mcp/registry.js#L1-L181" target="_blank" rel="noreferrer">agent/src/mcp/registry.js#L1-L181</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/mcp/client.js#L1-L184" target="_blank" rel="noreferrer">agent/src/mcp/client.js#L1-L184</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/mcp/mcp-config.js#L1-L129" target="_blank" rel="noreferrer">agent/src/mcp/mcp-config.js#L1-L129</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/tool-panel.js#L215-L244" target="_blank" rel="noreferrer">src/side_panel/tool-panel.js#L215-L244</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/agent-manager.js#L902-L928" target="_blank" rel="noreferrer">src/side_panel/agent-manager.js#L902-L928</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/mcp/registry.js#L1-L181" target="_blank" rel="noreferrer">agent/src/mcp/registry.js#L1-L181</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/mcp/client.js#L1-L184" target="_blank" rel="noreferrer">agent/src/mcp/client.js#L1-L184</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/mcp/mcp-config.js#L1-L129" target="_blank" rel="noreferrer">agent/src/mcp/mcp-config.js#L1-L129</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L1900-L2021" target="_blank" rel="noreferrer">agent/src/server.js#L1900-L2021</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/tool-executor.js#L547-L588" target="_blank" rel="noreferrer">src/background/tool-executor.js#L547-L588</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/tool-panel.js#L215-L244" target="_blank" rel="noreferrer">src/side_panel/tool-panel.js#L215-L244</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/agent-manager.js#L902-L928" target="_blank" rel="noreferrer">src/side_panel/agent-manager.js#L902-L928</a></li></ul><h2 id="性能与并发控制" tabindex="-1">性能与并发控制 <a class="header-anchor" href="#性能与并发控制" aria-label="Permalink to &quot;性能与并发控制&quot;">​</a></h2><ul><li><strong>配置缓存</strong>：mcp-config.js 使用内存缓存和 mtime 判断，避免频繁读盘。</li><li><strong>写入互斥</strong>：saveMcpConfig 使用 Promise 链式锁，保证并发写串行化。</li><li><strong>工具列表缓存</strong>：client.js 在 connect 后缓存 tools 数组，后续 getMcpTools 直接读取内存。</li><li><strong>扩展端并发拉取</strong>：tool-executor.js 并行拉取 tools 和 servers，减少等待时间。</li><li><strong>连接复用</strong>：registry.js 以 serverId 为键缓存 McpClient，避免重复连接。</li></ul><p>需要注意：</p><ul><li>当前实现没有显式的工具调用限流或超时控制，工具调用耗时取决于远端 MCP Server。</li><li>如果某个 MCP Server 不稳定，建议通过 toggle 禁用，而不是无限重试。</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/mcp/mcp-config.js#L14-L26" target="_blank" rel="noreferrer">agent/src/mcp/mcp-config.js#L14-L26</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/mcp/mcp-config.js#L69-L79" target="_blank" rel="noreferrer">agent/src/mcp/mcp-config.js#L69-L79</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/mcp/client.js#L114-L122" target="_blank" rel="noreferrer">agent/src/mcp/client.js#L114-L122</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/tool-executor.js#L569-L573" target="_blank" rel="noreferrer">src/background/tool-executor.js#L569-L573</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/mcp/registry.js#L19-L20" target="_blank" rel="noreferrer">agent/src/mcp/registry.js#L19-L20</a></li></ul><h2 id="安全与错误处理" tabindex="-1">安全与错误处理 <a class="header-anchor" href="#安全与错误处理" aria-label="Permalink to &quot;安全与错误处理&quot;">​</a></h2><ul><li><strong>认证与 CORS</strong>：server.js 对大多数接口要求 Bearer Token，并对 Chrome 扩展来源放行 CORS。</li><li><strong>输入校验</strong>：/api/mcp/call 校验 serverId 和 toolName。</li><li><strong>错误传播</strong>：client.js 将 SDK 错误包装为国际化消息；registry.js 对未连接或未找到服务器返回错误。</li><li><strong>日志</strong>：server.js 记录 mcp_tool_call 等系统事件，便于审计。</li><li><strong>配置解析失败保护</strong>：mcp-config.js 解析失败时降级为空配置，不阻断启动。</li></ul><p>潜在风险点：</p><ul><li>stdio 模式下 command/args/env 由配置决定，应视为可信配置来源；若配置来源不可信，需额外校验。</li><li>MCP Server 返回的 tool description 和 inputSchema 会被透传到扩展端，UI 渲染时应做基本防护。</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L438-L443" target="_blank" rel="noreferrer">agent/src/server.js#L438-L443</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L1916-L1922" target="_blank" rel="noreferrer">agent/src/server.js#L1916-L1922</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/mcp/client.js#L129-L157" target="_blank" rel="noreferrer">agent/src/mcp/client.js#L129-L157</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/mcp/registry.js#L116-L128" target="_blank" rel="noreferrer">agent/src/mcp/registry.js#L116-L128</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/mcp/mcp-config.js#L52-L63" target="_blank" rel="noreferrer">agent/src/mcp/mcp-config.js#L52-L63</a></li></ul><h2 id="生命周期管理" tabindex="-1">生命周期管理 <a class="header-anchor" href="#生命周期管理" aria-label="Permalink to &quot;生命周期管理&quot;">​</a></h2><ul><li><strong>启动初始化</strong>：server.js 启动时可通过 initializeMcpRegistry 连接所有启用的 MCP Server。</li><li><strong>动态连接</strong>：connectMcpServer 支持运行时连接指定服务器，先断开已有连接再新建。</li><li><strong>动态断开</strong>：disconnectMcpServer 清理 Client 并从 Map 删除。</li><li><strong>关闭清理</strong>：shutdownMcpRegistry 遍历所有 Client 调用 disconnect 并清空 Map。</li><li><strong>热重载限制</strong>：由于 MCP 连接和工具缓存存在于进程内存中，修改 Agent 源码后必须重启进程才能生效。</li></ul><pre class="mermaid">stateDiagram-v2
[*] --&gt; 未连接
未连接 --&gt; 已连接 : &quot;connectMcpServer()&quot;
已连接 --&gt; 已连接 : &quot;callMcpTool()&quot;
已连接 --&gt; 未连接 : &quot;disconnectMcpServer()&quot;
未连接 --&gt; 已连接 : &quot;initializeMcpRegistry()&quot;
已连接 --&gt; 已关闭 : &quot;shutdownMcpRegistry()&quot;
未连接 --&gt; 已关闭 : &quot;shutdownMcpRegistry()&quot;
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/mcp/registry.js#L26-L55" target="_blank" rel="noreferrer">agent/src/mcp/registry.js#L26-L55</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/mcp/registry.js#L133-L177" target="_blank" rel="noreferrer">agent/src/mcp/registry.js#L133-L177</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/mcp/registry.js#L26-L55" target="_blank" rel="noreferrer">agent/src/mcp/registry.js#L26-L55</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/mcp/registry.js#L133-L177" target="_blank" rel="noreferrer">agent/src/mcp/registry.js#L133-L177</a></li></ul><h2 id="分组、命名空间与版本机制" tabindex="-1">分组、命名空间与版本机制 <a class="header-anchor" href="#分组、命名空间与版本机制" aria-label="Permalink to &quot;分组、命名空间与版本机制&quot;">​</a></h2><ul><li><strong>分组</strong>：MCP 工具按 serverId 分组，UI 层按服务聚合展示。</li><li><strong>命名空间</strong>：工具名称来自远端 MCP Server，registry.js 在扁平化时保留 serverId 和 serverName，形成“服务名/工具名”的隐式命名空间。</li><li><strong>版本</strong>：client.js 在连接后获取 serverInfo 和 capabilities，但当前注册表并未将版本信息合并到工具列表中；serverInfo 主要用于状态展示。</li></ul><p>因此，当前版本的“版本管理”更偏向“服务端能力探测”，而非严格的语义化版本控制。</p><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/mcp/registry.js#L89-L108" target="_blank" rel="noreferrer">agent/src/mcp/registry.js#L89-L108</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/mcp/client.js#L109-L122" target="_blank" rel="noreferrer">agent/src/mcp/client.js#L109-L122</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/agent-manager.js#L902-L928" target="_blank" rel="noreferrer">src/side_panel/agent-manager.js#L902-L928</a></li></ul><h2 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h2><ul><li><strong>错误处理</strong><ul><li>始终检查工具调用结果中的 success 字段。</li><li>对未连接服务器优先调用 disconnect 或 toggle 禁用。</li><li>捕获 MCP Server 返回的 error.message，避免向用户暴露内部堆栈。</li></ul></li><li><strong>性能优化</strong><ul><li>避免频繁重连同一 MCP Server；利用 registry.js 的连接复用。</li><li>批量刷新工具列表时，先清理旧工具再注入，避免脏状态。</li><li>对不常用的 MCP Server，按需连接，不要全部保持长连接。</li></ul></li><li><strong>安全检查</strong><ul><li>不要信任远端 MCP Server 返回的描述和 schema 作为执行依据。</li><li>stdio 模式的 command/args/env 应由可信配置源生成。</li><li>对工具调用结果进行长度和内容过滤，防止注入。</li></ul></li><li><strong>i18n</strong><ul><li>扩展端 UI 文案应从 shared locales 动态读取，不应硬编码中文。</li><li>Agent 端语言通过 server.js 的请求入口同步到各子模块。</li></ul></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/mcp/client.js#L129-L157" target="_blank" rel="noreferrer">agent/src/mcp/client.js#L129-L157</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/mcp/registry.js#L116-L128" target="_blank" rel="noreferrer">agent/src/mcp/registry.js#L116-L128</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L428-L443" target="_blank" rel="noreferrer">agent/src/server.js#L428-L443</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/shared/locales/en.js#L970-L985" target="_blank" rel="noreferrer">src/shared/locales/en.js#L970-L985</a></li></ul><h2 id="自定义工具开发指南" tabindex="-1">自定义工具开发指南 <a class="header-anchor" href="#自定义工具开发指南" aria-label="Permalink to &quot;自定义工具开发指南&quot;">​</a></h2><p>如果你要开发一个 MCP Server，使其能被 ai-helper-agent 发现和调用，应遵循以下契约：</p><ol><li><p><strong>实现 MCP Server</strong></p><ul><li>支持 MCP 协议（JSON-RPC 2.0）。</li><li>暴露 <code>listTools</code>，返回工具元数据，至少包含 name、description、inputSchema。</li><li>暴露 <code>callTool</code>，接收 name 和 arguments，返回 content 和 isError。</li></ul></li><li><p><strong>选择传输方式</strong></p><ul><li>stdio：适合本地命令行工具，配置 command、args、env、cwd。</li><li>SSE/streamableHttp/websocket：适合网络服务，配置 url 和可选 headers。</li></ul></li><li><p><strong>在 Agent 端添加配置</strong></p><ul><li>编辑 <code>~/.ai-helper-agent/mcp_servers.json</code>，或通过 Agent 的 <code>/api/mcp/servers</code> 接口添加。</li><li>确保 id 唯一，enabled 为 true。</li></ul></li><li><p><strong>验证连接与工具</strong></p><ul><li>调用 <code>/api/mcp/servers</code> 查看连接状态。</li><li>调用 <code>/api/mcp/tools</code> 确认工具列表。</li><li>调用 <code>/api/mcp/call</code> 测试工具执行。</li></ul></li><li><p><strong>扩展端集成</strong></p><ul><li>扩展端会自动拉取工具列表并注入执行器。</li><li>UI 上按服务维度展示，可在侧边栏或服务管理器中启用/禁用服务。</li></ul></li></ol><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/mcp/client.js#L50-L94" target="_blank" rel="noreferrer">agent/src/mcp/client.js#L50-L94</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/mcp/mcp-config.js#L86-L98" target="_blank" rel="noreferrer">agent/src/mcp/mcp-config.js#L86-L98</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L1846-L1913" target="_blank" rel="noreferrer">agent/src/server.js#L1846-L1913</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L2013-L2021" target="_blank" rel="noreferrer">agent/src/server.js#L2013-L2021</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/tool-executor.js#L547-L588" target="_blank" rel="noreferrer">src/background/tool-executor.js#L547-L588</a></li></ul><h2 id="故障排查" tabindex="-1">故障排查 <a class="header-anchor" href="#故障排查" aria-label="Permalink to &quot;故障排查&quot;">​</a></h2><p>常见问题与定位思路：</p><ul><li><p><strong>MCP 工具列表为空</strong></p><ul><li>检查全局 MCP 开关是否开启。</li><li>检查服务器是否 enabled。</li><li>检查 <code>/api/mcp/servers</code> 中 connected 是否为 true。</li><li>检查远端 MCP Server 是否正确实现 listTools。</li></ul></li><li><p><strong>工具调用失败</strong></p><ul><li>检查 serverId 和 toolName 是否正确。</li><li>检查 Client 是否 connected。</li><li>查看 server.js 中 mcp_tool_call 日志。</li><li>检查 client.js 返回的错误消息。</li></ul></li><li><p><strong>配置保存失败</strong></p><ul><li>检查 <code>~/.ai-helper-agent/mcp_servers.json</code> 权限。</li><li>检查 JSON 格式是否合法。</li><li>观察 mcp-config.js 的解析错误日志。</li></ul></li><li><p><strong>连接反复失败</strong></p><ul><li>检查 command/url 是否正确。</li><li>检查网络可达性。</li><li>考虑暂时 toggle 禁用该服务，避免影响其他工具。</li></ul></li><li><p><strong>扩展端看不到 MCP 工具</strong></p><ul><li>检查 tool-executor.js 是否成功拉取 tools。</li><li>检查 disabledServerIds 是否包含目标服务。</li><li>检查 UI 层的服务级开关是否排除该服务。</li></ul></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/tool-executor.js#L547-L588" target="_blank" rel="noreferrer">src/background/tool-executor.js#L547-L588</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/mcp/registry.js#L116-L128" target="_blank" rel="noreferrer">agent/src/mcp/registry.js#L116-L128</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/mcp/client.js#L129-L157" target="_blank" rel="noreferrer">agent/src/mcp/client.js#L129-L157</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/mcp/mcp-config.js#L52-L79" target="_blank" rel="noreferrer">agent/src/mcp/mcp-config.js#L52-L79</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/tool-panel.js#L215-L244" target="_blank" rel="noreferrer">src/side_panel/tool-panel.js#L215-L244</a></li></ul><h2 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h2><p>MCP 工具注册表是一个以配置为中心、以协议客户端为核心的工具扩展机制。它不依赖本地文件系统扫描，而是通过 MCP 协议从远端 Server 发现工具；它通过注册表统一管理连接、缓存工具、转发调用；扩展端则负责拉取工具定义并注入执行体系。对于开发者而言，最重要的是保证 MCP Server 协议正确、配置可信、错误可观测，并在 Agent 进程变更后及时重启。</p>`,122)])])}const u=r(a,[["render",n]]);export{m as __pageData,u as default};
